{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Guided sound sessions and intensives in {{CITY}}, {{STATE}}. Immerse in concentrated listening to reset, rest, and re-tune.">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body class="site-root">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary">
        <a href="/events.html">Gatherings</a>
        <a href="/private-sessions.html">Private Sessions</a>
        <a href="/pricing.html">Investment</a>
        <a href="/about.html">Our Way</a>
        <a href="/faq.html">FAQ</a>
        <a href="/book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
    </div>
  </header>

  <main>
    <!-- Hero: immersive invitation + micro pricing comparator -->
    <section class="hero" id="hero">
      <div class="pattern-overlay" aria-hidden="true"></div>
      <div class="wrap hero-grid">
        <div class="hero-copy">
          <h1 class="hero-title">Sound as a small, precise ritual</h1>
          <p class="lead">We guide concentrated sound sessions designed to steady the breath, clarify attention, and leave you carrying tuned focus into the day.</p>

          <div class="hero-controls">
            <div class="price-card">
              <div class="pc-top">Next Intensive: <strong id="next-event-title">--</strong></div>
              <div class="pc-bottom">
                <div class="comparator" data-targets='{"monthly":30,"package":250}'>
                  <button class="cmp-toggle" aria-pressed="false">Monthly</button>
                  <button class="cmp-toggle" aria-pressed="true">Package</button>
                  <div class="price-display">$<span class="price-number">250</span></div>
                  <div class="price-sub">per person • duo-friendly</div>
                </div>
              </div>
            </div>

            <a class="btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>

        <aside class="hero-aside">
          <div class="next-event" id="next-event-module">
            <h3>Upcoming Gathering</h3>
            <div class="event-card">
              <div class="event-date" id="next-event-date">—</div>
              <div class="event-info">
                <div id="next-event-desc">Check our Events page for schedule and seating.</div>
                <a href="/events.html" class="link">See full calendar</a>
              </div>
            </div>
          </div>

          <div class="cred-strip">
            <span class="cred">Certified facilitators</span>
            <span class="cred">Limited capacity</span>
            <span class="cred">Sound-sanitized space</span>
          </div>
        </aside>
      </div>
    </section>

    <!-- Myth vs Truth -->
    <section class="myth-truth wrap" id="myth-truth">
      <h2>Myths we unmake</h2>
      <div class="mt-grid">
        <div class="mt-item">
          <h3>Myth: It's passive</h3>
          <p>Truth: Listening is an active re-tuning. We give clear cues and intentional transitions so you leave grounded and practical.</p>
        </div>
        <div class="mt-item">
          <h3>Myth: One size fits all</h3>
          <p>Truth: Sessions land with layers — ambient tone, focused bowls, and brief breath practices — to meet varied nervous systems.</p>
        </div>
        <div class="mt-item">
          <h3>Myth: Hard to fit in</h3>
          <p>Truth: We curate compact intensives alongside deeper packages for your schedule and objective.</p>
        </div>
      </div>
    </section>

    <!-- Pillars -->
    <section class="pillars wrap">
      <h2>Our guiding pillars</h2>
      <div class="pillars-grid">
        <div class="pillar">
          <strong>Precision</strong>
          <p>Sounds arranged with clear intent to support attention and nervous-system regulation.</p>
        </div>
        <div class="pillar">
          <strong>Practicality</strong>
          <p>Simple cues and takeaways you can fold into daily routines.</p>
        </div>
        <div class="pillar">
          <strong>Safety</strong>
          <p>Contraindications honored; we provide alternatives and suggest medical clearance when needed.</p>
        </div>
      </div>
    </section>

    <!-- Case Notes: Proof Gallery with rotating testimonials + badges -->
    <section class="case-notes wrap" id="case-notes">
      <h2>Proof Gallery</h2>
      <p class="muted">Short notes from attendees and organizational partners.</p>

      <div class="proof-grid">
        <div class="testimonials" id="testimonial-rotator" aria-live="polite">
          <!-- JS fills testimonials -->
        </div>

        <aside class="badges" id="cred-badges">
          <h3>Creds & Partners</h3>
          <ul>
            <li class="badge" data-tip="Local mindfulness center partnership">Mindful Harbor</li>
            <li class="badge" data-tip="Corporate wellbeing programming">Studio Collective</li>
            <li class="badge" data-tip="Professional clinician referral network">WellPath Clinicians</li>
          </ul>
        </aside>
      </div>
    </section>

    <!-- FAQ micro -->
    <section class="faq wrap" id="faq-teaser">
      <h2>Quick questions</h2>
      <dl>
        <dt>How long is a session?</dt>
        <dd>Gatherings run 60–75 minutes. Private sessions tailored 45–90 minutes.</dd>
        <dt>Do I need experience?</dt>
        <dd>No. Instructions are given; all experience levels welcomed.</dd>
        <dt>Contraindications?</dt>
        <dd>People with epilepsy, certain auditory conditions, or pregnancy should consult a clinician and contact us in advance. See full FAQ for details.</dd>
      </dl>
      <a class="link" href="/faq.html">Full FAQ</a>
    </section>

    <!-- CTA -->
    <section class="cta wrap" id="cta">
      <div class="cta-box">
        <h2>Reserve a place to re-tune</h2>
        <p>Small groups and private offerings. We keep capacity limited for quality and safety.</p>
        <a class="btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <p class="muted">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="f-left">
        <div class="brand-foot">{{BUSINESS_NAME}}</div>
        <div class="addr">{{CITY}}, {{STATE}}</div>
      </div>
      <div class="f-right">
        <nav class="foot-nav">
          <a href="/about.html">Our Way</a>
          <a href="/pricing.html">Investment</a>
          <a href="/contact.html">Contact</a>
        </nav>
        <div class="small">© <span id="yr"></span> {{BUSINESS_NAME}}</div>
      </div>
    </div>
  </footer>

  <!-- Accessible tooltip container -->
  <div id="tooltip" role="status" aria-live="polite" class="tooltip" hidden></div>
</body>
</html>"} 
