{"path":"assets/css/styles.css","content":"/* Base styles for sound bath site */
:root{
  --bg:#0f1012; --card:#0f1316; --accent:#b7e3d7; --muted:#9aa5a1; --glass:rgba(255,255,255,0.04);
  --radius:12px; --maxw:1100px; --pad:18px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#eef0ec;background:linear-gradient(180deg,var(--bg),#071015);}
.wrap{max-width:var(--maxw);margin:0 auto;padding:28px}
.site-header{background:linear-gradient(180deg,rgba(0,0,0,0.2),transparent);position:sticky;top:0;z-index:20;backdrop-filter:blur(4px)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{color:var(--accent);font-weight:700;text-decoration:none}
.main-nav a{color:#dfe9e3;margin-left:18px;text-decoration:none}
.main-nav .cta{background:var(--accent);color:#07201a;padding:10px 14px;border-radius:8px}
.hero{padding:60px 0;position:relative;color:#e9efe9}
.pattern-overlay{position:absolute;inset:0;background-image:url("assets/img/pattern.svg");opacity:0.06;mix-blend-mode:overlay}
.hero-grid{display:grid;grid-template-columns:1fr 320px;gap:28px;align-items:start}
.hero-title{font-size:clamp(24px,4vw,40px);margin:0 0 12px}
.lead{color:var(--muted);margin:0 0 18px}
.hero-controls{display:flex;gap:12px;align-items:center}
.price-card{background:var(--glass);padding:12px;border-radius:12px;color:#dff6f0}
.pc-top{font-size:13px;color:var(--muted)}
.price-display{font-size:22px;font-weight:700;margin-top:6px}
.btn-primary{background:#c3f2e2;color:#022018;padding:10px 16px;border-radius:10px;text-decoration:none}
.hero-aside{align-self:start}
.next-event h3{margin:0 0 12px}
.event-card{background:rgba(255,255,255,0.02);padding:12px;border-radius:10px;display:flex;gap:12px}
.event-date{font-weight:700}
.cred-strip{display:flex;gap:8px;margin-top:12px}
.cred{font-size:13px;padding:6px 8px;background:rgba(255,255,255,0.02);border-radius:8px}
.myth-truth{padding:36px 0}
.mt-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.mt-item{background:var(--card);padding:16px;border-radius:12px}
.pillars{padding:36px 0}
.pillars-grid{display:flex;gap:16px}
.pillar{flex:1;background:rgba(255,255,255,0.02);padding:14px;border-radius:12px}
.case-notes{padding:36px 0}
.proof-grid{display:grid;grid-template-columns:1fr 240px;gap:18px}
.testimonials{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:16px;border-radius:12px;min-height:160px;display:flex;align-items:center;justify-content:center}
.testimonial{max-width:720px;text-align:left}
.testimonial p{margin:0 0 12px}
.testimonial .who{font-size:13px;color:var(--muted)}
.badges{background:rgba(255,255,255,0.02);padding:12px;border-radius:12px}
.badges ul{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:8px}
.badge{background:#0b1416;color:var(--accent);padding:8px;border-radius:8px;cursor:help}
.faq{padding:24px 0}
.cta{padding:36px 0}
.cta-box{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:20px;border-radius:12px;text-align:center}
.site-footer{padding:18px 0;color:var(--muted)}
.site-footer .wrap{display:flex;justify-content:space-between;align-items:center}
.tooltip{position:fixed;z-index:40;background:#021210;color:var(--accent);padding:8px 10px;border-radius:8px;border:1px solid rgba(255,255,255,0.03);font-size:13px}
/* Pricing comparator */
.comparator{display:flex;flex-direction:column;align-items:flex-start}
.cmp-toggle{background:transparent;border:1px solid rgba(255,255,255,0.06);color:var(--muted);padding:6px 8px;border-radius:8px;margin-right:6px}
.price-number{display:inline-block;min-width:48px;text-align:right}
/* Responsive */
@media(max-width:880px){
  .hero-grid{grid-template-columns:1fr}
  .proof-grid{grid-template-columns:1fr}
  .mt-grid{grid-template-columns:1fr}
  .pillars-grid{flex-direction:column}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Document-ready
  function q(s){return document.querySelector(s)}
  function qa(s){return document.querySelectorAll(s)}

  // Year in footer
  var yr=q('#yr'); if(yr) yr.textContent=new Date().getFullYear();

  // Mock next-event data (would be seeded server-side)
  var nextEvent = {title:'Resonance Intensive — Evening', date:'Mar 10, 2026', desc:'An hour of guided tones and practical integration.'};
  var neTitle=q('#next-event-title'); var neDate=q('#next-event-date'); var neDesc=q('#next-event-desc');
  if(neTitle) neTitle.textContent=nextEvent.title;
  if(neDate) neDate.textContent=nextEvent.date;
  if(neDesc) neDesc.textContent=nextEvent.desc;

  // Pricing Comparator (works for any .comparator)
  function initComparators(){
    var comps = document.querySelectorAll('.comparator');
    comps.forEach(function(comp){
      var targetsAttr = comp.getAttribute('data-targets');
      var targets = targetsAttr ? JSON.parse(targetsAttr) : {monthly:30,package:250};
      var toggles = [];
      var els = comp.querySelectorAll('.cmp-toggle');
      els.forEach(function(btn){ toggles.push(btn); btn.addEventListener('click',function(){
          // set pressed
          els.forEach(function(b){b.setAttribute('aria-pressed','false')});
          btn.setAttribute('aria-pressed','true');
          var label = btn.textContent.trim().toLowerCase();
          var val = targets[label] || targets['package'];
          animateNumber(comp.querySelector('.price-number'),val);
        })});
      // initialize: find pressed or default to package
      var active = comp.querySelector('.cmp-toggle[aria-pressed="true"]') || els[els.length-1];
      if(active){ var lab=active.textContent.trim().toLowerCase(); animateNumber(comp.querySelector('.price-number'), targets[lab] || targets['package']); }
    });
  }

  function animateNumber(el, to){ if(!el) return; var from = parseFloat(el.textContent)||0; var duration=500; var start=performance.now();
    function step(ts){ var p=Math.min(1,(ts-start)/duration); var val = Math.round(from + (to-from)*ease(p)); el.textContent=val; if(p<1) requestAnimationFrame(step); }
    requestAnimationFrame(step);
  }
  function ease(t){ return t<0.5?2*t*t: -1+(4-2*t)*t }

  // Testimonials rotator + badges tooltips
  var testimonials = [
    {quote:'I arrived distracted and left with a practical reset — the clarity lasted days.',who:'— M.S., educator',badges:['Mindful Harbor']},
    {quote:'Thoughtful facilitation and a respectful, calm room. Great for teams.',who:'— R.T., product lead',badges:['Studio Collective']},
    {quote:'A contained, precise practice that works with how my nervous system actually responds.',who:'— L.K., therapist',badges:['WellPath Clinicians']}
  ];

  function renderTestimonial(i){
    var wrap=q('#testimonial-rotator'); if(!wrap) return;
    var t=testimonials[i];
    wrap.innerHTML='';
    var div=document.createElement('div'); div.className='testimonial';
    div.innerHTML='<p>"'+t.quote+'"</p><div class="who">'+t.who+'</div>';
    wrap.appendChild(div);
    // highlight badges list items that match
    var badgeEls = document.querySelectorAll('#cred-badges .badge');
    badgeEls.forEach(function(b){
      var tip = b.getAttribute('data-tip')||b.textContent;
      if(t.badges && t.badges.indexOf(b.textContent.trim())>-1){ b.style.boxShadow='0 0 0 2px rgba(183,227,215,0.12)'; }
      else b.style.boxShadow='none';
    });
  }

  var cur=0; function cycleTestimonials(){ renderTestimonial(cur); cur=(cur+1)%testimonials.length; }
  cycleTestimonials(); var rot=setInterval(cycleTestimonials,5000);

  // Badge tooltips (simple)
  var tooltip=q('#tooltip');
  document.addEventListener('mouseover',function(e){
    var el = e.target.closest('.badge'); if(!el) return;
    var txt = el.getAttribute('data-tip')||el.textContent;
    tooltip.textContent=txt; tooltip.hidden=false;
    var r = el.getBoundingClientRect(); tooltip.style.top = (r.bottom + 8)+'px'; tooltip.style.left = (r.left)+'px';
  });
  document.addEventListener('mouseout',function(e){ if(e.target.closest && e.target.closest('.badge')){ tooltip.hidden=true; }});

  // Keyboard accessibility: pause rotator on focus
  document.addEventListener('focusin',function(e){ if(e.target.closest && e.target.closest('#testimonial-rotator')) clearInterval(rot); });

  // Init comparators
  initComparators();

  // Simple safety note console log (visible to site maintainers)
  console.info('Site initialized. Reminder: enforce contraindications and contact clinicians when necessary.');
})();
"} 
